    d=os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
        k,h,w=m.group(1),int(m.group(2)),int(m.group(3))
        rows=[r.split() for r in t[m.end():].split('\n')[:h]]
        if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
            G[k]=[[int(x) for x in r] for r in rows]
    return G
G=load()

def comps(g):
    H,W=len(g),len(g[0]); seen=set(); res=[]
    for i in range(H):
        for j in range(W):
            if g[i][j] and (i,j) not in seen:
                col=g[i][j]; stack=[(i,j)]; cells=[]
                while stack:
                    y,x=stack.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==col: stack.append((ny,nx))
                res.append((col,cells))
    return res

def stats(cells):
    ys=[y for y,_ in cells]; xs=[x for _,x in cells]
    h=max(ys)-min(ys)+1; w=max(xs)-min(xs)+1
    hp=sum(1 for r in range(h) if len({x for y,x in cells if y==r})>=2)
    vp=sum(1 for c in range(w) if len({y for y,x in cells if x==c})>=2)
    hr=sum(1 for r in range(h) for c in range(w) if (r,c) in set(cells) and (r,c+1) in set(cells))
    vr=sum(1 for r in range(h) for c in range(w) if (r,c) in set(cells) and (r+1,c) in set(cells))
    return h,w,hr,vr,hr-vr

