    H,W=len(g),len(g[0]); seen=set(); res=[]
    div=[j for j in range(W) if all(g[r][j]==4 for r in range(H))]
    dcol=div[0] if div else None
    for i in range(H):
        for j in range(W):
            if g[i][j] not in (0,dcol) and (i,j) not in seen:
                col=g[i][j]; st=[(i,j)]; cl=[]
                while st:
                    y,x=st.pop()
                    if (y,x) in seen: continue
                    seen.add((y,x)); cl.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<H and 0<=nx<W and g[ny][nx]==col: st.append((ny,nx))
                res.append((col,cl))
    return dcol,res
